export interface DistributionPoint {
  label: string;
  value: number;
}

export interface TrendPoint {
  month: string;
  low: number;
  moderate: number;
  high: number;
  critical: number;
}

export interface DashboardStats {
  totalProjects: number;
  lowRisk: number;
  moderateRisk: number;
  highRisk: number;
  criticalRisk: number;
  verificationRequired: number;
  averageEvidenceQuality: number;
  riskDistribution: DistributionPoint[];
  categoryBreakdown: DistributionPoint[];
  anomalySignals: DistributionPoint[];
  trend: TrendPoint[];
  flaggedProjects: Project[];
}

export interface ActivityItem {
  id: string;
  type: string;
  title: string;
  detail: string;
  time: string;
  /** @nullable */
  projectId?: string | null;
}

export interface EvidenceImage {
  id: number;
  projectId: string;
  /** @nullable */
  originalFilename: string | null;
  /** @nullable */
  mimeType: string | null;
  /** @nullable */
  fileSizeBytes: number | null;
  /** @nullable */
  width: number | null;
  /** @nullable */
  height: number | null;
  /**
     * Actual EXIF capture timestamp, if present in the file. Never the upload time.
     * @nullable
     */
  capturedAt: string | null;
  /** @nullable */
  gpsLatitude: number | null;
  /** @nullable */
  gpsLongitude: number | null;
  /** @nullable */
  gpsAccuracyMeters: number | null;
  /** @nullable */
  sha256: string | null;
  /** @nullable */
  perceptualHash: string | null;
  /** @nullable */
  label: string | null;
  source: string;
  uploadedAt: string;
}

export interface InvestigationInput {
  status: string;
  notes: string;
  decision: string;
}

export interface ProgressRecord {
  id: number;
  projectId: string;
  reportDate: string;
  progressPercent: number;
  /** @nullable */
  note: string | null;
  source: string;
  createdAt: string;
}

export interface ProgressRecordInput {
  /** ISO date (YYYY-MM-DD) the progress was actually observed/reported — not today's date. */
  reportDate: string;
  /**
     * @minimum 0
     * @maximum 100
     */
  progressPercent: number;
  note?: string;
}

export interface UploadRecord { [key: string]: unknown }

export interface UploadInput {
  filename: string;
  /** Raw register rows; the API validates each row against ProjectInput. */
  records: UploadRecord[];
  /** Spreadsheet row number for each record, including the header row. */
  rowNumbers?: number[];
}

export interface UploadRowError {
  row: number;
  errors: string[];
}

export interface UploadResult {
  imported: number;
  rejected: number;
  missingFields: string[];
  qualityScore: number;
  rowErrors: UploadRowError[];
}

export type ListProjectsParams = {
search?: string;
priority?: ListProjectsPriority;
district?: string;
category?: string;
sort?: ListProjectsSort;
/**
 * @minimum 1
 */
page?: number;
/**
 * @minimum 1
 * @maximum 100
 */
pageSize?: number;
};

export type ListProjectsPriority = typeof ListProjectsPriority[keyof typeof ListProjectsPriority];


export const ListProjectsPriority = {
  LOW: 'LOW',
  MODERATE: 'MODERATE',
  HIGH: 'HIGH',
  CRITICAL: 'CRITICAL',
} as const;

export type ListProjectsSort = typeof ListProjectsSort[keyof typeof ListProjectsSort];


export const ListProjectsSort = {
  priority: 'priority',
  financial: 'financial',
  visual: 'visual',
  evidence: 'evidence',
  date: 'date',
} as const;

